import json,pathlib,copy
from bs4 import BeautifulSoup
r=pathlib.Path('work/research-2026');p=json.load(open(r/'reviewed.json'));xs=json.load(open(r/'verified-sites144-next100-review.json'));before={};dec=[]
assert not (r/'featured142-before.json').exists()
fix={19:'Distributes food products and supports food-service programs, including school nutrition.',30:'A communications and public-relations consultancy providing strategy, messaging and stakeholder outreach.',44:'Sells clothing marketed as electromagnetic-field shielding apparel.',49:'Manufactures and supplies medical equipment, protective apparel and other healthcare supplies.',55:'Develops smartphone-based AI tools marketed for personal health checks and monitoring.',59:'A North Carolina retailer selling hemp-derived products, including edibles, beverages and vaping products.',68:'Develops hybrid-electric vertical-takeoff aircraft and unmanned cargo systems.',84:'A research and advocacy organization focused on policy for access to blockchain-based financial markets.',93:'Manufactures and supplies medical equipment, protective apparel and other healthcare supplies.',97:'Develops automated construction technology and provides building design and construction services.'}
special={1:'The official renewable-fuels site names Grapevine Energy Holdings, LLC in its footer; claimed emissions advantages are not independently validated.',9:'The official Green Ammo AS page describes electronic blank-ammunition training systems. Zero-risk marketing is not adopted as a safety guarantee.',11:'The official transmission-development site names Grid United LLC in its footer; planned lines are not presented as operating infrastructure.',14:'The official Grist Mill About body explicitly identifies the CEO of Grist Mill Exchange and describes commercial-data services.',23:'The company site describes a planned southwest Louisiana carbon-sequestration hub. Future storage operations are not treated as current measured performance.',25:'The official site names G.W. Lisk Company, Inc. and its Clifton Springs address and describes engineered valves, sensors and solenoids.',30:'The official site substantiates communications consulting. A filing-specific trucking advocacy statement was omitted from the general business description.',32:'The official chemical-products site names Halocarbon, LLC in its footer.',33:'HaloMD describes administrative support for payment-dispute resolution. This description does not adopt its legal interpretations or advertised win rates.',41:'The official site explicitly names Hart Health Strategies Inc. and describes healthcare lobbying and consulting.',44:'The official HAVN site identifies the apparel brand. Its claims about EMF health risks, fertility and health protection are not treated as established findings.',49:'The official Health Supply US site describes medical supplies and government contracting. Product-specific compliance is not generalized to all products; original records remain separately traceable.',55:'The official Helfie AI site describes personal-health applications. Diagnostic accuracy, medical approval and claimed health benefits are not independently established.',68:'The official aircraft-development site names HopFlyt Inc. in its footer. Staff experience and design targets are not completed production or demonstrated performance.',74:'The official quantitative-trading site names Hudson River Trading LLC as its trademark holder and site owner.',84:'The official Hyperliquid Policy Center body describes blockchain-market policy research and advocacy. This page does not establish a tax-code classification.',85:'The official HyperloopTT site describes transportation development and testing. Test infrastructure is not an operating passenger network.',87:'The official Hypoparathyroidism Association site describes patient education, support and advocacy and identifies nonprofit status.',93:'The official Health Supply US site describes medical supplies and government contracting. Unverified FDA-compliance and representative-specific wording were removed from this business description; source records remain separate.',97:'The official ICON site names ICON Technology, Inc. and describes building design and construction technology; unverified location and material-specific detail was omitted.'}
for n,v in enumerate(xs):
 if v['decision']!='confirmed' or n in [8,27,45,60]:continue
 i=v['id'];assert p[i]['name']==v['original_name'] and p[i]['review_outcome']!='confirmed';before[i]=copy.deepcopy(p[i]);note=special.get(n,'Official organization body text identifies this organization and supports the activity summarized. Existing ownership evidence is retained without inferring additional ownership from its name.')
 p[i].update(description=fix.get(n,v['description']),notes=note,identity_evidence=note,review_outcome='confirmed',checked_at='2026-09-13',as_of='2026-09-13')
 e=v['fetched_evidence'][0];assert e['http_status']==200
 s=BeautifulSoup(open(e['cache_path']).read(),'html.parser')
 for t in s(['script','style','nav','header']):t.decompose()
 body=' '.join(s.stripped_strings)
 ss={s['url']:s for s in p[i]['sources']};ss[e['url']]={'url':e['url'],'label':'Official organization evidence','claim':note};p[i]['sources']=list(ss.values());dec.append(dict(id=i,name=p[i]['name'],decision='confirmed',notes=note,fetched_evidence=v['fetched_evidence'],reviewed_body=body))
(r/'featured142-before.json').write_text(json.dumps(before,indent=2)+'\n');(r/'featured142-decisions.json').write_text(json.dumps(dec,indent=2)+'\n')
(r/'featured142-deferred.json').write_text(json.dumps([dict(id=xs[n]['id'],name=xs[n]['original_name'],reason=reason) for n,reason in [(8,'Only footer and navigation retrieved; substantive activity not supported.'),(27,'Generic law-firm messaging does not support proposed employment practice.'),(45,'News-only page does not substantiate proposed shelter/equipment description or legal transition.'),(60,'Platform activity evident but exact Inc identity requires additional legal evidence.')]],indent=2)+'\n')
for f in [r/'reviewed.json',pathlib.Path('outputs/2026-research-trial/profiles.json')]:f.write_text(json.dumps(p,ensure_ascii=False,indent=2)+'\n')
pathlib.Path('lobbying-map/research/reviewed-2026.json').write_text(json.dumps(p,ensure_ascii=False));print(len(dec),'identity confirmations saved')
